package com.jarvis.phone;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.net.Uri;import android.provider.Settings;import android.view.KeyEvent;import java.util.*;import java.util.regex.*;
public class CommandEngine{public interface Reply{void say(String s);}final Context c;final LocalVault v;public CommandEngine(Context c){this.c=c;v=new LocalVault(c);}public void execute(String q,Reply r){if(q==null)return;String l=q.toLowerCase(Locale.ROOT);String n=v.get("wake_name","Jarvis");l=l.replaceFirst("(?i)^"+Pattern.quote(n)+"[ ,:-]*","").trim();if(l.contains("bluetooth")){open(Settings.ACTION_BLUETOOTH_SETTINGS);r.say("Bluetooth settings खोल दी।");return;}if(l.contains("wifi")||l.contains("wi-fi")){open(Settings.ACTION_WIFI_SETTINGS);r.say("Wi-Fi settings खोल दी।");return;}if(l.equals("home")||l.contains("होम जाओ")){global(2);r.say("Home।");return;}if(l.equals("back")||l.contains("पीछे जाओ")){global(1);r.say("Back।");return;}if(l.startsWith("tap ")||l.startsWith("दबाओ ")){String t=q.substring(q.indexOf(' ')+1);JarvisAccessibilityService s=JarvisAccessibilityService.get();r.say(s!=null&&s.tapText(t)?"दबा दिया।":"वो text नहीं मिला।");return;}if(l.contains("notification")||l.contains("नोटिफिकेशन")){r.say(v.get("latest_notification","कोई notification capture नहीं हुई।"));return;}if(l.contains("screen पर क्या")||l.contains("स्क्रीन पर क्या")){r.say(v.get("latest_screen_text","Screen text उपलब्ध नहीं।"));return;}if(l.contains("गाना चल")||l.equals("play")){media(KeyEvent.KEYCODE_MEDIA_PLAY);r.say("Play।");return;}if(l.contains("गाना रोक")||l.equals("pause")){media(KeyEvent.KEYCODE_MEDIA_PAUSE);r.say("Pause।");return;}if(l.startsWith("call ")||l.startsWith("कॉल ")){String x=q.substring(q.indexOf(' ')+1).replaceAll("[^0-9+]","");if(x.isEmpty()){r.say("Number बोलो।");return;}Intent i=new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+x));i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);r.say("Dialer खोल दिया।");return;}if(l.startsWith("open ")||l.startsWith("खोलो ")){String a=q.substring(q.indexOf(' ')+1).trim();Intent i=find(a);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);r.say(a+" खोल दिया।");}else r.say("App नहीं मिला।");return;}r.say("ये command अभी v1 में नहीं है।");}void open(String a){Intent i=new Intent(a);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);}void global(int a){JarvisAccessibilityService s=JarvisAccessibilityService.get();if(s!=null)s.performGlobalAction(a);}void media(int k){AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);a.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,k));a.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,k));}Intent find(String name){PackageManagerHelper h=new PackageManagerHelper(c);return h.find(name);}static class PackageManagerHelper{Context c;PackageManagerHelper(Context c){this.c=c;}Intent find(String n){android.content.pm.PackageManager p=c.getPackageManager();for(android.content.pm.ApplicationInfo a:p.getInstalledApplications(0)){String l=p.getApplicationLabel(a).toString();if(l.equalsIgnoreCase(n)||l.toLowerCase().contains(n.toLowerCase())){Intent i=p.getLaunchIntentForPackage(a.packageName);if(i!=null)return i;}}return null;}}}
